"""In-memory CPU control-plane agent implementing the protocol lifecycle."""
from __future__ import annotations

import re
import struct

from .create_dfa import DENY, create
from syntax import PolicyError, parse_policy

_U32 = 4294967295
_HEX48 = re.compile(r"[0-9A-Fa-f]{48}\Z")
_MISSING = object()

class Rejected(Exception):
    pass

class ImageRec:
    __slots__ = ("accept", "rows", "cell_count", "refs")
    def __init__(self, image, cell_count):
        self.accept = image["accept"]
        self.rows = image["rows"]
        self.cell_count = cell_count
        self.refs = 0

class Context:
    __slots__ = ("epoch", "state")
    def __init__(self, epoch, state):
        self.epoch = epoch
        self.state = state

class Unit:
    __slots__ = ("ns", "pid", "gen", "service", "mark", "contexts")
    def __init__(self, ns, pid, gen, service, mark=0, contexts=None):
        self.ns = ns
        self.pid = pid
        self.gen = gen
        self.service = service
        self.mark = mark
        self.contexts = {} if contexts is None else contexts
    @property
    def triple(self):
        return (self.ns, self.pid, self.gen)

class Packet:
    __slots__ = ("epoch", "state", "destination", "wire", "receipt")
    def __init__(self, epoch, state, destination, wire):
        self.epoch = epoch
        self.state = state
        self.destination = destination
        self.wire = wire
        self.receipt = None          # (unit_triple, rid, epoch, state)

class Connection:
    __slots__ = ("gen", "mark", "packets")
    def __init__(self, gen):
        self.gen = gen
        self.mark = 0
        self.packets = {}

class FileRec:
    __slots__ = ("gen", "epoch", "state")
    def __init__(self, gen, epoch, state):
        self.gen = gen
        self.epoch = epoch
        self.state = state

class MemoryMap:
    """Compatibility no-op view of the historical CPU transition map."""
    def __init__(self):
        self.entries = {}
    def __setitem__(self, key, value):
        self.entries[key] = value

class Agent:
    def __init__(self, services, limits):
        self.services = services
        self.limits = limits
        ordered = sorted(services, key=lambda s: s["label"])
        self.sym_of = {s["name"]: i for i, s in enumerate(ordered)}
        self.label_of = {s["name"]: s["label"] for s in services}
        self.m = len(ordered)

        self.images = {}
        self.active = None
        self.stage_hw = 0
        self.cells_used = 0

        self.units = {}              # (namespace,pid) -> Unit
        self.unit_hw = {}            # (namespace,pid) -> generation high-water
        self.context_count = 0

        self.connections = {}        # connection id -> Connection
        self.conn_hw = {}            # connection id -> generation high-water
        self.packet_count = 0

        self.files = {}              # file id -> FileRec
        self.file_hw = {}            # file id -> generation high-water

    # ---- small helpers -------------------------------------------------
    def _live_unit(self, u):
        rec = self.units.get((u[0], u[1]))
        if rec is None or rec.gen != u[2]:
            raise Rejected()
        return rec

    def _open_conn(self, c):
        rec = self.connections.get(c[0])
        if rec is None or rec.gen != c[1]:
            raise Rejected()
        return rec

    def _current_file(self, f):
        rec = self.files.get(f[0])
        if rec is None or rec.gen != f[1]:
            raise Rejected()
        return rec

    def _advance(self, rec, state, service):
        if state == DENY:
            return DENY
        return rec.rows[state][self.sym_of[service]]

    def _wire(self, epoch, state, destination_label, stream, connection_gen):
        return struct.pack(">4sIIIII", b"EMC4", epoch, state,
                           destination_label, stream, connection_gen).hex()

    @staticmethod
    def _wire_ok(candidate, expected):
        if type(candidate) is not str or len(candidate) != 48:
            return False
        if _HEX48.fullmatch(candidate) is None:
            return False
        return candidate.lower() == expected

    def _inc_ref(self, epoch):
        rec = self.images.get(epoch)
        if rec is None:
            raise Rejected()
        rec.refs += 1

    def _dec_ref(self, epoch):
        rec = self.images.get(epoch)
        if rec is None or rec.refs <= 0:
            raise Rejected()
        rec.refs -= 1

    # ---- replay --------------------------------------------------------
    def event(self, event, parsed=_MISSING):
        try:
            return self._event(event, parsed)
        except (Rejected, PolicyError, KeyError, IndexError, ValueError,
                struct.error):
            return {"error": "rejected"}

    def _event(self, e, parsed):
        op = e["op"]
        if op == "stage":
            return self._stage(e, parsed)
        if op == "commit":
            ep = e["epoch"]
            if ep not in self.images:
                raise Rejected()
            self.active = ep
            return {"ok": True}
        if op == "retire":
            ep = e["epoch"]
            rec = self.images.get(ep)
            if rec is None or self.active == ep or rec.refs != 0:
                raise Rejected()
            del self.images[ep]
            self.cells_used -= rec.cell_count
            return {"ok": True}
        if op == "spawn":
            return self._spawn(e)
        if op == "clone":
            return self._clone(e)
        if op == "exit":
            return self._exit(e)
        if op == "begin":
            return self._begin(e)
        if op == "finish":
            return self._finish(e)
        if op == "open":
            return self._open(e)
        if op == "send":
            return self._send(e)
        if op == "recv":
            return self._recv(e)
        if op == "close":
            return self._close(e)
        if op == "store":
            return self._store(e)
        if op == "load":
            return self._load(e)
        if op == "unlink":
            return self._unlink(e)
        if op == "inspect":
            return self._inspect()
        raise Rejected()

    def _stage(self, e, parsed):
        ep = e["epoch"]
        if ep <= self.stage_hw:
            raise Rejected()
        if len(self.images) >= self.limits["images"]:
            raise Rejected()
        if parsed is _MISSING:
            try:
                parsed = parse_policy(e["policy"])
            except PolicyError:
                raise Rejected()
        elif parsed is None:
            raise Rejected()
        image = create(e["policy"], self.services, parsed=parsed)
        cell_count = 0
        for row in image["rows"]:
            for target in row:
                if target != DENY:
                    cell_count += 1
        if self.cells_used + cell_count > self.limits["cells"]:
            raise Rejected()
        # Publication is a single dictionary insertion after every check.
        rec = ImageRec(image, cell_count)
        self.images[ep] = rec
        self.stage_hw = ep
        self.cells_used += cell_count
        return {"ok": True, "epoch": ep, "image": image}

    def _spawn(self, e):
        u = e["unit"]
        pair = (u[0], u[1])
        if pair in self.units or u[2] <= self.unit_hw.get(pair, 0):
            raise Rejected()
        service = e["service"]
        if service not in self.sym_of:
            raise Rejected()
        if len(self.units) >= self.limits["units"]:
            raise Rejected()
        unit = Unit(u[0], u[1], u[2], service)
        self.units[pair] = unit
        self.unit_hw[pair] = u[2]
        return {"ok": True}

    def _clone(self, e):
        parent = self._live_unit(e["parent"])
        c = e["child"]
        cpair = (c[0], c[1])
        if cpair in self.units or c[2] <= self.unit_hw.get(cpair, 0):
            raise Rejected()
        nctx = len(parent.contexts)
        if len(self.units) >= self.limits["units"]:
            raise Rejected()
        if self.context_count + nctx > self.limits["contexts"]:
            raise Rejected()
        copies = {rid: Context(ctx.epoch, ctx.state)
                  for rid, ctx in parent.contexts.items()}
        child = Unit(c[0], c[1], c[2], parent.service,
                     mark=parent.mark, contexts=copies)
        # Commit unit and all copies.  The image references are independent
        # per copied context.
        self.units[cpair] = child
        self.unit_hw[cpair] = c[2]
        self.context_count += nctx
        for ctx in copies.values():
            self._inc_ref(ctx.epoch)
        return {"ok": True}

    def _exit(self, e):
        u = self._live_unit(e["unit"])
        pair = (u.ns, u.pid)
        for ctx in u.contexts.values():
            self._dec_ref(ctx.epoch)
        self.context_count -= len(u.contexts)
        del self.units[pair]
        return {"ok": True}

    def _begin(self, e):
        u = self._live_unit(e["unit"])
        rid = e["rid"]
        if self.active is None:
            raise Rejected()
        rec = self.images.get(self.active)
        if rec is None or rid <= u.mark:
            raise Rejected()
        if self.context_count >= self.limits["contexts"]:
            raise Rejected()
        state = self._advance(rec, 0, u.service)
        u.contexts[rid] = Context(self.active, state)
        u.mark = rid
        self.context_count += 1
        rec.refs += 1
        return {"ok": True, "epoch": self.active, "state": state}

    def _finish(self, e):
        u = self._live_unit(e["unit"])
        rid = e["rid"]
        ctx = u.contexts.pop(rid, None)
        if ctx is None:
            raise Rejected()
        self.context_count -= 1
        self._dec_ref(ctx.epoch)
        rec = self.images[ctx.epoch]
        allow = ctx.state != DENY and bool(rec.accept[ctx.state])
        return {"ok": True, "allow": allow}

    def _open(self, e):
        c = e["connection"]
        cid, gen = c[0], c[1]
        if cid in self.connections or gen <= self.conn_hw.get(cid, 0):
            raise Rejected()
        if len(self.connections) >= self.limits["connections"]:
            raise Rejected()
        self.connections[cid] = Connection(gen)
        self.conn_hw[cid] = gen
        return {"ok": True}

    def _send(self, e):
        u = self._live_unit(e["unit"])
        ctx = u.contexts.get(e["rid"])
        if ctx is None:
            raise Rejected()
        conn = self._open_conn(e["connection"])
        stream = e["stream"]
        if stream <= conn.mark:
            raise Rejected()
        destination = e["destination"]
        label = self.label_of.get(destination)
        if label is None:
            raise Rejected()
        if self.packet_count >= self.limits["packets"]:
            raise Rejected()
        wire = self._wire(ctx.epoch, ctx.state, label, stream, conn.gen)
        rec = self.images.get(ctx.epoch)
        if rec is None:
            raise Rejected()
        conn.packets[stream] = Packet(ctx.epoch, ctx.state, destination, wire)
        conn.mark = stream
        self.packet_count += 1
        rec.refs += 1
        return {"ok": True, "wire": wire}

    def _recv(self, e):
        conn = self._open_conn(e["connection"])
        stream = e["stream"]
        packet = conn.packets.get(stream)
        if packet is None:
            raise Rejected()
        u = self._live_unit(e["unit"])
        if u.service != packet.destination:
            raise Rejected()
        wire = e["wire"]
        if wire is not None and not self._wire_ok(wire, packet.wire):
            raise Rejected()
        rid = e["rid"]
        receipt = packet.receipt
        if receipt is not None:
            r_triple, r_rid, r_epoch, r_state = receipt
            if u.triple != r_triple or rid != r_rid:
                raise Rejected()
            ctx = u.contexts.get(rid)
            if ctx is None or ctx.epoch != r_epoch or ctx.state != r_state:
                raise Rejected()
            return {"ok": True, "epoch": r_epoch, "state": r_state}
        if rid <= u.mark:
            raise Rejected()
        if self.context_count >= self.limits["contexts"]:
            raise Rejected()
        rec = self.images.get(packet.epoch)
        if rec is None:
            raise Rejected()
        state = self._advance(rec, packet.state, u.service)
        ctx = Context(packet.epoch, state)
        u.contexts[rid] = ctx
        u.mark = rid
        self.context_count += 1
        rec.refs += 1
        receipt = (u.triple, rid, packet.epoch, state)
        packet.receipt = receipt
        return {"ok": True, "epoch": packet.epoch, "state": state}

    def _close(self, e):
        conn = self._open_conn(e["connection"])
        cid = e["connection"][0]
        for packet in conn.packets.values():
            self._dec_ref(packet.epoch)
        self.packet_count -= len(conn.packets)
        del self.connections[cid]
        return {"ok": True}

    def _store(self, e):
        u = self._live_unit(e["unit"])
        ctx = u.contexts.get(e["rid"])
        if ctx is None:
            raise Rejected()
        fid, gen = e["file"][0], e["file"][1]
        cur = self.files.get(fid)
        if cur is None:
            if gen <= self.file_hw.get(fid, 0):
                raise Rejected()
            if len(self.files) >= self.limits["files"]:
                raise Rejected()
            self._inc_ref(ctx.epoch)
            self.files[fid] = FileRec(gen, ctx.epoch, ctx.state)
            self.file_hw[fid] = gen
            return {"ok": True}
        if gen != cur.gen:
            raise Rejected()
        old_epoch = cur.epoch
        # Atomic overwrite: adjust the one file reference in place.
        if old_epoch != ctx.epoch:
            self._dec_ref(old_epoch)
            self._inc_ref(ctx.epoch)
        cur.epoch = ctx.epoch
        cur.state = ctx.state
        return {"ok": True}

    def _load(self, e):
        cur = self._current_file(e["file"])
        u = self._live_unit(e["unit"])
        rid = e["rid"]
        if rid <= u.mark:
            raise Rejected()
        if self.context_count >= self.limits["contexts"]:
            raise Rejected()
        rec = self.images.get(cur.epoch)
        if rec is None:
            raise Rejected()
        state = self._advance(rec, cur.state, u.service)
        u.contexts[rid] = Context(cur.epoch, state)
        u.mark = rid
        self.context_count += 1
        rec.refs += 1
        return {"ok": True, "epoch": cur.epoch, "state": state}

    def _unlink(self, e):
        f = e["file"]
        cur = self._current_file(f)
        self._dec_ref(cur.epoch)
        del self.files[f[0]]
        return {"ok": True}

    def _inspect(self):
        entries = []
        for ep in sorted(self.images):
            rec = self.images[ep]
            entries.append([ep, len(rec.rows), rec.cell_count, rec.refs])
        return {
            "ok": True,
            "active": self.active,
            "images": entries,
            "units": len(self.units),
            "contexts": self.context_count,
            "connections": len(self.connections),
            "packets": self.packet_count,
            "files": len(self.files),
        }
